enum QuantityError: Error {
    case notANumber
    case notPositive
}

func parseQuantity(_ text: String) throws -> Int {
    guard let value = Int(text) else {
        throw QuantityError.notANumber
    }
    guard value > 0 else {
        throw QuantityError.notPositive
    }
    return value
}

let value = try? parseQuantity("12")
print(value ?? -1)
